    "\n  query EkfrequenzQuery($id: UUID!) {\n    allEkfrequenzs(filter: { id: { equalTo: $id }, ektyp: { isNull: false } }) {\n      nodes {\n        id\n        kontrolljahre\n        ektyp\n      }\n    }\n  }\n": types.EkfrequenzQueryDocument,
    "\n  query EkplansQuery($jahr: Int!, $tpopId: UUID!) {\n    allEkplans(\n      filter: {\n        jahr: { greaterThanOrEqualTo: $jahr }\n        tpopId: { equalTo: $tpopId }\n      }\n    ) {\n      nodes {\n        id\n      }\n    }\n  }\n": types.EkplansQueryDocument,
    "\n  query EkfrequenzQueryForSetStartjahr($id: UUID!) {\n    ekfrequenzById(id: $id) {\n      id\n      kontrolljahreAb\n      kontrolljahre\n    }\n  }\n": types.EkfrequenzQueryForSetStartjahrDocument,
    "\n  query TpopkontrQueryForSetStartjahr($tpopId: UUID!) {\n    tpopById(id: $tpopId) {\n      id\n      tpopkontrsByTpopId {\n        nodes {\n          id\n          jahr\n        }\n      }\n    }\n  }\n": types.TpopkontrQueryForSetStartjahrDocument,
    "\n  query TpopmassnQueryForSetStartjahr($tpopId: UUID!) {\n    tpopById(id: $tpopId) {\n      id\n      tpopmassnsByTpopId {\n        nodes {\n          id\n          jahr\n        }\n      }\n    }\n  }\n": types.TpopmassnQueryForSetStartjahrDocument,
    "\n  query EkplanApQuery($ids: [UUID!]) {\n    allAps(filter: { id: { in: $ids } }) {\n      nodes {\n        id\n        ekzaehleinheitsByApId(\n          filter: { zielrelevant: { equalTo: true } }\n          orderBy: TPOPKONTRZAEHL_EINHEIT_WERTE_BY_ZAEHLEINHEIT_ID__SORT_ASC\n        ) {\n          nodes {\n            id\n            tpopkontrzaehlEinheitWerteByZaehleinheitId {\n              id\n              code\n              text\n            }\n          }\n        }\n      }\n    }\n  }\n": types.EkplanApQueryDocument,
    "\n  mutation createUsermessage($id: UUID!, $userName: String!) {\n    createUsermessage(\n      input: { usermessage: { userName: $userName, messageId: $id } }\n    ) {\n      usermessage {\n        id\n      }\n    }\n  }\n": types.CreateUsermessageDocument,
    "\n  query UsermessagesQuery($name: String!, $aYearAgo: Datetime!) {\n    allMessages(\n      filter: {\n        active: { equalTo: true }\n        time: { greaterThanOrEqualTo: $aYearAgo }\n      }\n      orderBy: TIME_ASC\n    ) {\n      nodes {\n        id\n        message\n        time\n        usermessagesByMessageId(filter: { userName: { equalTo: $name } }) {\n          totalCount\n        }\n      }\n    }\n    allUsers {\n      nodes {\n        id\n        name\n      }\n    }\n  }\n": types.UsermessagesQueryDocument,
    "\n          query apberById($apberId: UUID!) {\n            apberById(id: $apberId) {\n              id\n              jahr\n            }\n          }\n        ": types.ApberByIdDocument,
    "\n          query AktPopListAps($jahr: Int!) {\n            jberAktPop(jahr: $jahr) {\n              nodes {\n                artname\n                id\n                pop100\n                pop200\n                popTotal\n                pop100Diff\n                pop200Diff\n                popTotalDiff\n              }\n            }\n          }\n        ": types.AktPopListApsDocument,
    "\n          query apberuebersichtByIdForApberForYear($apberuebersichtId: UUID!) {\n            apberuebersichtById(id: $apberuebersichtId) {\n              id\n              jahr\n            }\n          }\n        ": types.ApberuebersichtByIdForApberForYearDocument,
    "\n  query jberForApberForYear($jahr: Int!) {\n    # this works fine from graphiql but from here: after historizing crashes (times out)\n    jberAbc(jahr: $jahr) {\n      nodes {\n        artname\n        id\n        startJahr\n        bearbeiter\n        bearbeitung\n        a3LPop\n        a3LTpop\n        a4LPop\n        a4LTpop\n        a5LPop\n        a5LTpop\n        a7LPop\n        a7LTpop\n        a8LPop\n        a8LTpop\n        a9LPop\n        a9LTpop\n        b1LPop\n        b1LTpop\n        b1FirstYear\n        b1RPop\n        b1RTpop\n        c1LPop\n        c1LTpop\n        c1RPop\n        c1RTpop\n        c1FirstYear\n        firstMassn\n        c2RPop\n        c2RTpop\n        c3RPop\n        c3RTpop\n        c4RPop\n        c4RTpop\n        c5RPop\n        c5RTpop\n        c6RPop\n        c6RTpop\n        c7RPop\n        c7RTpop\n        erfolg\n        erfolgVorjahr\n      }\n    }\n  }\n": types.JberForApberForYearDocument,
    "\n          query apFilterControllerQuery($id: UUID!) {\n            apById(id: $id) {\n              id\n              bearbeitung\n            }\n          }\n        ": types.ApFilterControllerQueryDocument,
    "\n          mutation createAdresseForAdresseForm {\n            createAdresse(input: { adresse: {} }) {\n              adresse {\n                id\n              }\n            }\n          }\n        ": types.CreateAdresseForAdresseFormDocument,
