    "\n          query benutzerForNewUser {\n            allUsers(\n              orderBy: NAME_ASC\n              filter: {\n                role: { in: [\"apflora_ap_writer\", \"apflora_ap_reader\"] }\n              }\n            ) {\n              nodes {\n                id\n                name\n                role\n              }\n            }\n          }\n        ": types.BenutzerForNewUserDocument,
    "\n          mutation createApUserForApMutation($apId: UUID!, $name: String) {\n            createApUser(input: { apUser: { apId: $apId, userName: $name } }) {\n              apUser {\n                id\n              }\n            }\n          }\n        ": types.CreateApUserForApMutationDocument,
    "\n          query apUsersForApQuery($apId: UUID!) {\n            allApUsers(\n              filter: {\n                apId: { equalTo: $apId }\n                # uncommented because ap_writer's dont see other names otherwise\n                # userByUserName: {\n                #   role: { in: [\"apflora_ap_writer\", \"apflora_ap_reader\"] }\n                # }\n              }\n            ) {\n              nodes {\n                id\n                userName\n                userByUserName {\n                  id\n                  role\n                }\n              }\n            }\n          }\n        ": types.ApUsersForApQueryDocument,
    "\n  query apFilesQuery($apId: UUID!) {\n    apById(id: $apId) {\n      id\n      aeTaxonomyByArtId {\n        id\n        artname\n      }\n    }\n  }\n": types.ApFilesQueryDocument,
    "\n          mutation deleteApHistoryForHistorienForm($id: UUID!, $year: Int!) {\n            deleteApHistoryByIdAndYear(input: { id: $id, year: $year }) {\n              apHistory {\n                id\n                year\n              }\n            }\n          }\n        ": types.DeleteApHistoryForHistorienFormDocument,
    "\n  query apHistoryQuery($apId: UUID!) {\n    apById(id: $apId) {\n      id\n      label\n      artId\n      aeTaxonomyByArtId {\n        id\n        artname\n      }\n      bearbeitung\n      apBearbstandWerteByBearbeitung {\n        id\n        text\n      }\n      startJahr\n      umsetzung\n      apUmsetzungWerteByUmsetzung {\n        id\n        text\n      }\n      artId\n      bearbeiter\n      adresseByBearbeiter {\n        id\n        name\n      }\n      ekfBeobachtungszeitpunkt\n      projId\n      projektByProjId {\n        id\n        name\n      }\n      changedBy\n    }\n    allApHistories(filter: { id: { equalTo: $apId } }, orderBy: YEAR_DESC) {\n      totalCount\n      nodes {\n        id\n        year\n        artId\n        aeTaxonomyByArtId {\n          id\n          artname\n        }\n        bearbeitung\n        apBearbstandWerteByBearbeitung {\n          id\n          text\n        }\n        startJahr\n        umsetzung\n        apUmsetzungWerteByUmsetzung {\n          id\n          text\n        }\n        artId\n        bearbeiter\n        adresseByBearbeiter {\n          id\n          name\n        }\n        ekfBeobachtungszeitpunkt\n      }\n    }\n    allAdresses(orderBy: NAME_ASC) {\n      nodes {\n        value: id\n        label: name\n      }\n    }\n    allApBearbstandWertes(orderBy: SORT_ASC) {\n      nodes {\n        value: code\n        label: text\n      }\n    }\n    allApUmsetzungWertes(orderBy: SORT_ASC) {\n      nodes {\n        value: code\n        label: text\n      }\n    }\n  }\n": types.ApHistoryQueryDocument,
    "\n          mutation createApForApForm($projId: UUID!) {\n            createAp(input: { ap: { projId: $projId } }) {\n              ap {\n                id\n                projId\n              }\n            }\n          }\n        ": types.CreateApForApFormDocument,
    "\n          mutation deleteAp($id: UUID!) {\n            deleteApById(input: { id: $id }) {\n              ap {\n                id\n              }\n            }\n          }\n        ": types.DeleteApDocument,
    "\n  query ApAeTaxonomiesQuery($filter: AeTaxonomyFilter!) {\n    allAeTaxonomies(first: 8, filter: $filter, orderBy: TAX_ART_NAME_ASC) {\n      nodes {\n        value: id\n        label: taxArtName\n      }\n    }\n  }\n": types.ApAeTaxonomiesQueryDocument,
    "\n  query apAuswertungErfolg($id: UUID!) {\n    allApbers(\n      filter: { apId: { equalTo: $id }, beurteilung: { in: [1, 3, 4, 5, 6] } }\n      orderBy: JAHR_ASC\n    ) {\n      nodes {\n        id\n        jahr\n        beurteilung\n        apErfkritWerteByBeurteilung {\n          id\n          text\n        }\n      }\n    }\n  }\n": types.ApAuswertungErfolgDocument,
    "\n  query apAuswertungPopMenge($id: UUID!, $jahr: Int!) {\n    # function: apflora.ap_ausw_pop_menge\n    apAuswPopMenge(apid: $id, jahr: $jahr) {\n      nodes {\n        jahr\n        values\n      }\n    }\n    allEkzaehleinheits(\n      filter: { apId: { equalTo: $id }, zielrelevant: { equalTo: true } }\n    ) {\n      nodes {\n        id\n        tpopkontrzaehlEinheitWerteByZaehleinheitId {\n          id\n          text\n        }\n      }\n    }\n    # do not need to filter further - is done in apAuswPopMenge\n    allPops(filter: { apId: { equalTo: $id } }, orderBy: [NR_ASC, NAME_ASC]) {\n      nodes {\n        id\n        nr\n        name\n        status\n      }\n    }\n  }\n": types.ApAuswertungPopMengeDocument,
    "\n  query popDataForPopStatus($apId: UUID!, $year: Int!) {\n    # function: pop_nach_status_for_jber\n    popNachStatusForJber(apid: $apId, year: $year) {\n      nodes {\n        year\n        a3Lpop\n        a4Lpop\n        a5Lpop\n        a7Lpop\n        a8Lpop\n        a9Lpop\n      }\n    }\n  }\n": types.PopDataForPopStatusDocument,
    "\n  query apAuswertungTpopKontrolliert($id: UUID!, $year: Int!) {\n    # function: tpop_kontrolliert_for_jber\n    tpopKontrolliertForJber(\n      apid: $id\n      filter: { year: { lessThanOrEqualTo: $year } }\n    ) {\n      nodes {\n        year\n        anzTpop\n        anzTpopber\n      }\n    }\n  }\n": types.ApAuswertungTpopKontrolliertDocument,
    "\n  query apAuswertungQuery($apId: UUID!) {\n    apById(id: $apId) {\n      id\n      aeTaxonomyByArtId {\n        id\n        artname\n      }\n    }\n  }\n": types.ApAuswertungQueryDocument,
