    "\n  query popForLowerNodesQuery($id: UUID!) {\n    popById(id: $id) {\n      id\n      tpopsByPopId {\n        nodes {\n          id\n        }\n      }\n      popbersByPopId {\n        nodes {\n          id\n        }\n      }\n      popmassnbersByPopId {\n        nodes {\n          id\n        }\n      }\n    }\n  }\n": types.PopForLowerNodesQueryDocument,
