    "\n  query treeContainerOpenLowerNodesQuery($id: UUID!) {\n    tpopById(id: $id) {\n      id\n      tpopmassnsByTpopId {\n        nodes {\n          id\n        }\n      }\n      tpopmassnbersByTpopId {\n        nodes {\n          id\n        }\n      }\n      tpopfeldkontrs: tpopkontrsByTpopId(\n        filter: { typ: { notEqualTo: \"Freiwilligen-Kontrolle\" } }\n      ) {\n        nodes {\n          id\n        }\n      }\n      tpopfreiwkontrs: tpopkontrsByTpopId(\n        filter: { typ: { equalTo: \"Freiwilligen-Kontrolle\" } }\n      ) {\n        nodes {\n          id\n        }\n      }\n      tpopbersByTpopId {\n        nodes {\n          id\n        }\n      }\n      beobsByTpopId {\n        nodes {\n          id\n        }\n      }\n    }\n  }\n": types.TreeContainerOpenLowerNodesQueryDocument,
    "\n  query tpopFolderOpenLowerNodesQuery($id: UUID!) {\n    popById(id: $id) {\n      id\n      tpopsByPopId {\n        nodes {\n          id\n          tpopmassnsByTpopId {\n            nodes {\n              id\n            }\n          }\n          tpopmassnbersByTpopId {\n            nodes {\n              id\n            }\n          }\n          tpopfeldkontrs: tpopkontrsByTpopId(\n            filter: { typ: { notEqualTo: \"Freiwilligen-Kontrolle\" } }\n          ) {\n            nodes {\n              id\n              tpopkontrzaehlsByTpopkontrId {\n                nodes {\n                  id\n                }\n              }\n            }\n          }\n          tpopfreiwkontrs: tpopkontrsByTpopId(\n            filter: { typ: { equalTo: \"Freiwilligen-Kontrolle\" } }\n          ) {\n            nodes {\n              id\n              tpopkontrzaehlsByTpopkontrId {\n                nodes {\n                  id\n                }\n              }\n            }\n          }\n          tpopbersByTpopId {\n            nodes {\n              id\n            }\n          }\n          beobsByTpopId {\n            nodes {\n              id\n            }\n          }\n        }\n      }\n      popbersByPopId {\n        nodes {\n          id\n        }\n      }\n      popmassnbersByPopId {\n        nodes {\n          id\n        }\n      }\n    }\n  }\n": types.TpopFolderOpenLowerNodesQueryDocument,
