    "\n          query getNewEkfrequenzForEkfrequenzFolder($apId: UUID) {\n            allEkfrequenzs(filter: { apId: { equalTo: $apId } }) {\n              nodes {\n                id\n                anwendungsfall\n                apId\n                bemerkungen\n                code\n                ekAbrechnungstyp\n                ektyp\n                kontrolljahre\n                kontrolljahreAb\n                sort\n              }\n            }\n          }\n        ": types.GetNewEkfrequenzForEkfrequenzFolderDocument,
    "\n              mutation insertEkfrequenzForEkfrequenzFolder(\n                $apId: UUID!\n                $anwendungsfall: String\n                $bemerkungen: String\n                $changedBy: String\n                $code: String\n                $ekAbrechnungstyp: String\n                $ektyp: EkType\n                $kontrolljahre: [Int]\n                $kontrolljahreAb: EkKontrolljahreAb\n                $sort: Int\n              ) {\n                createEkfrequenz(\n                  input: {\n                    ekfrequenz: {\n                      apId: $apId\n                      anwendungsfall: $anwendungsfall\n                      bemerkungen: $bemerkungen\n                      code: $code\n                      ekAbrechnungstyp: $ekAbrechnungstyp\n                      ektyp: $ektyp\n                      kontrolljahre: $kontrolljahre\n                      kontrolljahreAb: $kontrolljahreAb\n                      sort: $sort\n                      changedBy: $changedBy\n                    }\n                  }\n                ) {\n                  ekfrequenz {\n                    id\n                    apId\n                    anwendungsfall\n                    bemerkungen\n                    code\n                    ekAbrechnungstyp\n                    ektyp\n                    kontrolljahre\n                    kontrolljahreAb\n                    sort\n                    changedBy\n                  }\n                }\n              }\n            ": types.InsertEkfrequenzForEkfrequenzFolderDocument,
    "\n          query apForEkfrequenzfolder($filter: ApFilter) {\n            allAps(orderBy: [LABEL_ASC], filter: $filter) {\n              nodes {\n                value: id\n                label\n                ekfrequenzsByApId {\n                  totalCount\n                }\n              }\n            }\n          }\n        ": types.ApForEkfrequenzfolderDocument,
