    "\n              mutation insertErfkritForErfkritFolder(\n                $apId: UUID!\n                $erfolg: Int\n                $kriterien: String\n                $changedBy: String\n              ) {\n                createErfkrit(\n                  input: {\n                    erfkrit: {\n                      apId: $apId\n                      erfolg: $erfolg\n                      kriterien: $kriterien\n                      changedBy: $changedBy\n                    }\n                  }\n                ) {\n                  erfkrit {\n                    id\n                    apId\n                    erfolg\n                    kriterien\n                    changedBy\n                  }\n                }\n              }\n            ": types.InsertErfkritForErfkritFolderDocument,
